/* scheduler.c - CPU scheduling policies (FR2)
 *
 * Implements FCFS, Round Robin, and non-preemptive Priority scheduling.
 * Each policy computes completion time, turnaround time, waiting time,
 * and averages. Output is generated by running the algorithm, not hard-coded.
 */

#include "campuscompute.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Tie-breaking rule: for jobs with equal arrival time (FCFS/RR) or equal
 * priority (Priority), the job with the smaller job_id is scheduled first.
 * This is deterministic and documented. */

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static job_t *copy_jobs(const job_t *jobs, int n) {
    job_t *copy = malloc((size_t)n * sizeof(job_t));
    if (!copy) return NULL;
    memcpy(copy, jobs, (size_t)n * sizeof(job_t));
    return copy;
}

static schedule_result_t *alloc_result(const char *name, int n, int max_events) {
    schedule_result_t *r = calloc(1, sizeof(*r));
    if (!r) return NULL;
    strncpy(r->name, name, sizeof(r->name) - 1);
    r->name[sizeof(r->name) - 1] = '\0';
    r->num_jobs = n;
    r->jobs = calloc((size_t)n, sizeof(job_t));
    /* max_events bounds the execution-timeline length (RR may emit more
     * events than jobs due to preemption). */
    r->exec_order = malloc((size_t)max_events * sizeof(int));
    if (!r->jobs || !r->exec_order) {
        free(r->jobs);
        free(r->exec_order);
        free(r);
        return NULL;
    }
    r->exec_len = 0;
    return r;
}

static void compute_metrics(schedule_result_t *r) {
    double tt_sum = 0, wt_sum = 0;
    for (int i = 0; i < r->num_jobs; i++) {
        job_t *j = &r->jobs[i];
        j->turnaround_time = j->completion_time - j->arrival_time;
        j->waiting_time = j->turnaround_time - j->cpu_burst;
        if (j->waiting_time < 0) j->waiting_time = 0;
        tt_sum += j->turnaround_time;
        wt_sum += j->waiting_time;
    }
    r->avg_turnaround = r->num_jobs ? tt_sum / r->num_jobs : 0.0;
    r->avg_waiting = r->num_jobs ? wt_sum / r->num_jobs : 0.0;
}

/* Sort jobs by arrival time, tie-break by job_id (ascending). */
static int cmp_arrival_then_id(const void *a, const void *b) {
    const job_t *ja = (const job_t *)a;
    const job_t *jb = (const job_t *)b;
    if (ja->arrival_time != jb->arrival_time)
        return ja->arrival_time - jb->arrival_time;
    return ja->job_id - jb->job_id;
}

/* Find index of highest priority job among ready ones.
 * Lower priority number = higher priority. Tie-break by job_id. */
static int pick_priority_index(job_t *jobs, int n, int current_time) {
    int best = -1;
    for (int i = 0; i < n; i++) {
        job_t *j = &jobs[i];
        if (j->status != JOB_STATUS_PENDING) continue;
        if (j->arrival_time > current_time) continue;
        if (best == -1) { best = i; continue; }
        job_t *bj = &jobs[best];
        if (j->priority < bj->priority) best = i;
        else if (j->priority == bj->priority && j->job_id < bj->job_id)
            best = i;
    }
    return best;
}

/* ------------------------------------------------------------------ */
/* FCFS                                                               */
/* ------------------------------------------------------------------ */

schedule_result_t *scheduler_fcfs(const job_t *jobs, int n) {
    job_t *copy = copy_jobs(jobs, n);
    if (!copy) return NULL;
    schedule_result_t *r = alloc_result("FCFS", n, n);
    if (!r) { free(copy); return NULL; }

    qsort(copy, (size_t)n, sizeof(job_t), cmp_arrival_then_id);

    int time = 0;
    for (int i = 0; i < n; i++) {
        job_t *j = &copy[i];
        if (time < j->arrival_time) time = j->arrival_time; /* idle gap */
        j->start_time = time;
        j->status = JOB_STATUS_RUNNING;
        r->exec_order[r->exec_len++] = j->job_id;
        time += j->cpu_burst;
        j->completion_time = time;
        j->status = JOB_STATUS_COMPLETED;
        r->jobs[i] = *j;
    }

    compute_metrics(r);
    free(copy);
    return r;
}

/* ------------------------------------------------------------------ */
/* Round Robin                                                        */
/* ------------------------------------------------------------------ */

schedule_result_t *scheduler_round_robin(const job_t *jobs, int n, int quantum) {
    if (quantum <= 0) quantum = 1;

    job_t *copy = copy_jobs(jobs, n);
    if (!copy) return NULL;
    /* Upper bound on dispatch events: one per CPU time unit plus jobs. */
    int total_burst = 0;
    for (int i = 0; i < n; i++) total_burst += copy[i].cpu_burst;
    schedule_result_t *r = alloc_result("Round Robin", n, total_burst + n);
    if (!r) { free(copy); return NULL; }

    /* Ready queue implemented as a simple circular index list. */
    int *ready = malloc((size_t)n * sizeof(int));
    int head = 0, tail = 0, inq = 0;
    int *enqueued = calloc((size_t)n, sizeof(int));
    int *rem = malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; i++) rem[i] = copy[i].cpu_burst;

    if (!ready || !enqueued || !rem) {
        free(copy); free(ready); free(enqueued); free(rem);
        free(r->jobs); free(r->exec_order); free(r);
        return NULL;
    }

    int time = 0;
    int completed = 0;
    int next_arrival = 0;

    /* Sort a helper array by arrival to know when jobs become ready. */
    int *order = malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; i++) order[i] = i;
    /* simple insertion sort by arrival then id */
    for (int i = 1; i < n; i++) {
        int key = order[i];
        int j = i - 1;
        while (j >= 0 &&
               (copy[order[j]].arrival_time > copy[key].arrival_time ||
                (copy[order[j]].arrival_time == copy[key].arrival_time &&
                 copy[order[j]].job_id > copy[key].job_id))) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = key;
    }

    while (completed < n) {
        /* Enqueue all jobs that have arrived by `time` and not yet queued. */
        while (next_arrival < n && copy[order[next_arrival]].arrival_time <= time) {
            int idx = order[next_arrival++];
            if (!enqueued[idx]) {
                ready[tail++] = idx;
                tail %= n;
                inq++;
                enqueued[idx] = 1;
            }
        }

        if (inq == 0) {
            /* CPU idle until next arrival. */
            time = copy[order[next_arrival]].arrival_time;
            continue;
        }

        int idx = ready[head++];
        head %= n;
        inq--;
        job_t *j = &copy[idx];

        if (j->start_time == -1 || j->start_time == 0) {
            /* first time running: record start_time if not already set.
             * start_time defaults to 0 in calloc; use remaining==cpu_burst
             * to detect first run. */
        }
        if (j->remaining == j->cpu_burst) j->start_time = time;

        int slice = (j->remaining < quantum) ? j->remaining : quantum;
        r->exec_order[r->exec_len++] = j->job_id;
        time += slice;
        j->remaining -= slice;

        /* Enqueue newly arrived jobs while/after this slice. */
        while (next_arrival < n && copy[order[next_arrival]].arrival_time <= time) {
            int nxt = order[next_arrival++];
            if (!enqueued[nxt]) {
                ready[tail++] = nxt;
                tail %= n;
                inq++;
                enqueued[nxt] = 1;
            }
        }

        if (j->remaining > 0) {
            /* re-queue at end */
            ready[tail++] = idx;
            tail %= n;
            inq++;
            enqueued[idx] = 1;
        } else {
            j->completion_time = time;
            j->status = JOB_STATUS_COMPLETED;
            completed++;
        }
        r->jobs[idx] = *j;
    }

    compute_metrics(r);

    free(copy);
    free(ready);
    free(enqueued);
    free(rem);
    free(order);
    return r;
}

/* ------------------------------------------------------------------ */
/* Non-preemptive Priority                                            */
/* ------------------------------------------------------------------ */

schedule_result_t *scheduler_priority(const job_t *jobs, int n) {
    job_t *copy = copy_jobs(jobs, n);
    if (!copy) return NULL;
    schedule_result_t *r = alloc_result("Priority (non-preemptive)", n, n);
    if (!r) { free(copy); return NULL; }

    int time = 0;
    int completed = 0;
    int *started = calloc((size_t)n, sizeof(int));

    while (completed < n) {
        int idx = pick_priority_index(copy, n, time);
        if (idx == -1) {
            /* No job ready yet; advance time to next arrival. */
            int min_arr = __INT_MAX__;
            for (int i = 0; i < n; i++)
                if (copy[i].status == JOB_STATUS_PENDING &&
                    copy[i].arrival_time < min_arr)
                    min_arr = copy[i].arrival_time;
            time = min_arr;
            continue;
        }

        job_t *j = &copy[idx];
        if (!started[idx]) { j->start_time = time; started[idx] = 1; }
        j->status = JOB_STATUS_RUNNING;
        r->exec_order[r->exec_len++] = j->job_id;
        time += j->cpu_burst;
        j->completion_time = time;
        j->status = JOB_STATUS_COMPLETED;
        r->jobs[idx] = *j;
        completed++;
    }

    compute_metrics(r);
    free(copy);
    free(started);
    return r;
}

/* ------------------------------------------------------------------ */
/* Printing                                                           */
/* ------------------------------------------------------------------ */

void scheduler_print_result(const schedule_result_t *r) {
    if (!r) return;
    printf("\n=== %s ===\n", r->name);
    printf("Tie-breaking rule: equal arrival/priority -> smaller job_id first\n");
    if (r->exec_len > 0) {
        printf("Execution order: ");
        for (int i = 0; i < r->exec_len; i++)
            printf("%d%s", r->exec_order[i], (i + 1 < r->exec_len) ? " -> " : "\n");
    }
    printf("%-8s %-12s %-10s %-10s %-14s %-14s %-12s\n",
           "JobID", "Arrival", "Burst", "Priority", "Start", "Completion", "Turnaround");
    printf("--------------------------------------------------------------------------------\n");
    for (int i = 0; i < r->num_jobs; i++) {
        const job_t *j = &r->jobs[i];
        printf("%-8d %-12d %-10d %-10d %-14d %-14d %-12d\n",
               j->job_id, j->arrival_time, j->cpu_burst, j->priority,
               j->start_time, j->completion_time, j->turnaround_time);
    }
    printf("--------------------------------------------------------------------------------\n");
    printf("%-8s %-12s %-10s %-10s %-14s %-14d %-12d\n",
           "Avg", "", "", "", "", (int)r->avg_turnaround, (int)r->avg_waiting);
    printf("Average Turnaround Time: %.2f\n", r->avg_turnaround);
    printf("Average Waiting Time:    %.2f\n", r->avg_waiting);
}

void scheduler_free_result(schedule_result_t *r) {
    if (!r) return;
    free(r->jobs);
    free(r->exec_order);
    free(r);
}
